require('dotenv').config();
const bcrypt=require('bcryptjs'); const crypto=require('node:crypto'); const {Pool}=require('pg');
(async()=>{if(!process.env.DATABASE_URL||!process.env.ADMIN_EMAIL||!process.env.ADMIN_PASSWORD||process.env.ADMIN_PASSWORD==='CHANGE_ME_NOW'||process.env.ADMIN_PASSWORD.length<14){console.error('Set DATABASE_URL, ADMIN_EMAIL, and a unique ADMIN_PASSWORD of at least 14 characters.');process.exit(1)}const p=new Pool({connectionString:process.env.DATABASE_URL});try{const email=process.env.ADMIN_EMAIL.toLowerCase();const exists=await p.query('SELECT id FROM users WHERE lower(email)=lower($1)',[email]);if(exists.rowCount){console.error('This email already exists; bootstrap will not change its role/password.');process.exitCode=1;return}const hash=await bcrypt.hash(process.env.ADMIN_PASSWORD,12);const code='AV-'+new Date().getFullYear()+'-ADMIN-'+crypto.randomBytes(3).toString('hex').toUpperCase();const ref='AVR-'+crypto.randomBytes(6).toString('hex').toUpperCase();await p.query("INSERT INTO users(member_code,full_name,email,password_hash,role,status,referral_code) VALUES($1,$2,$3,$4,'super_admin','active',$5)",[code,process.env.ADMIN_NAME||'Ashri Super Admin',email,hash,ref]);console.log('Initial Super Admin created. Store credentials securely and remove them from deployment environment when no longer needed.')}catch(e){console.error(e.message);process.exitCode=1}finally{await p.end()}})();
